/**
 * @method
 * @name fn_PopFindCorpChrgSW
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_PopFindCorpChrgSW = async function(pSecjGrpId, pSType) {

    let secuGrpStr = ""
    if(pSecjGrpId == "ST"){
    	if(pSType == "1")
    		secuGrpStr = "기업인수목적";
    	else	
    		secuGrpStr = "주권";
    } else {
		secuGrpStr = scwin.fn_getSecuGrpNm(pSecjGrpId);
	}

    let url = "/ui/lst/common/ULDSTF92009_SW.xml";
    let popTitle = secuGrpStr+"회사 선택";

    const opts = {
        id: "ULDSTF92009_SW",
        popupName: popTitle,
        width: 700,
        height: 950,
        frameModal: "top",
    };

    const popData = {STYPE: pSType, SECU_GRP_STR: secuGrpStr, SECJ_GRP_ID: pSecjGrpId }
    const res = await $c.win.openPopup(url, opts, popData);

    return res;
}


