/**
 * @method
 * @name fn_chkSymblDoubleInput
 * @description 심볼 중복체크
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_chkSymblDoubleInput = async function(symblTyp, symbl, symblCd, dtsObj) {
	//초기화
    scwin.glb.MSG_SYMBL_DOUBLE_INPUT = "";

    let str="";
	if (symblTyp == '1' || symblTyp == '3') {
		str = '영문회사';
	} else if (symblTyp == '2') {
		str = '영문종목';
	}

	if (symbl == "") {
		await $c.win.alert("["+str+"심볼]을 입력하세요.");
        return false;
	}

	if (symblTyp == '1') {
		if (symbl.length >= 7 ) {
		    await $c.win.alert("["+str+"심볼]을 6자리이내로 입력하세요.");
            return false;
		}
	} else if (symblTyp == '2' || symblTyp == '3') {
		if (symbl.length >= 8 ) {
			 await $c.win.alert("["+str+"심볼]을 7자리이내로 입력하세요.");
             return false;
		}
	}

	if(symblTyp == '3') symblTyp = '1';

	// let url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
	// url += "&DIV_IDX=" + DIV_R_CHK_SYMBL;
	// url += "&SYMBL_TYP=" + symblTyp;
	// url += "&SYMBL=" + symbl;
	// dts_Symbl.DataID = encodeURI(url);
	// dts_Symbl.Reset();

    const reqMap = {
        symbl: symbl,
        symblTyp: symblTyp,
    };
    const sbmOptions = {
        id: "sbm_selectOneSymbl",
        action: "/api/listing/lstproc/listinvstg-common/select-one-symbl",
        method: "get",
        // ref : "dma_codReq",
        // target: "dlt_codRes=body.COM_CHG_RSN_CD",
        // submitDoneHandler : scwin.sbm_selectOneSymbl_submitdone,
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

	let vCd = res.responseJSON.body.cd;
	let vNm = res.responseJSON.body.nm;

    //서버에서 컬럼에 null로 올때가 있어서 임시로 방어로직 추가
    if($c.util.isEmpty(vCd)) vCd = "";

    if (symblCd != vCd) {
		let msg = ""
		+ "이미 지정되어 있는 "+ str +"심볼을 입력하셨습니다.</br>"
		+ "다시 확인 하시고 입력 해 주십시오.</br></br>"
		+ "중복 데이터 내용 : </br>"
		+ "[" + vCd + "]"+ vNm + " </br>"

		scwin.glb.MSG_SYMBL_DOUBLE_INPUT = msg;
		return false;
	} else {
		let msg = "입력한 "+ str +"심볼을 사용할 수 있습니다";
		scwin.glb.MSG_SYMBL_DOUBLE_INPUT = msg;
		return true;
	}

}


