 * @name fn_isNewValueForDataSet
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_isNewValueForDataSet = function( dts , colName , checkValue) {
	for (let i = 1; i <= dts.CountRow; i++) { 
		if( dts.NameString( i  , colName  )  ==  checkValue ) {
			alert("이미 선택하신 사유가 있습니다.");
			return false;
		}
	}
	return true;

}
