/*
 * 일자,시간 체크 함수
 * isCheckCurDate : 오늘 날짜를 포함해서 비교를 할지 여부 ( 유가 : 미포함, 코스닥 : 포함 )
 */
/**
 * @method
 * @name checkDdTm
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.checkDdTm = function( gubun , obj  , msg , includeCurDate) {
	if ( gubun == "DD" ) { 
		if (obj.text.length != 8 ) { alert("[" + msg + "일]을 정확히 입력하세요."); obj.focus(); return false; }		

	  	let vCurDate = $c.utils.cGetToday("yyyymmdd");
	  	if( includeCurDate ) {
			if (vCurDate > $c.stf.getObjectValue(obj)) {
				alert("[" + msg + "일]을 현재일 이후로 입력하세요.");obj.focus();return false;
			}
		}
		else
		{
			if (vCurDate >= $c.stf.getObjectValue(obj)) {
				alert("[" + msg + "일]을 익일 이후로 입력하세요.");obj.focus();return false;
			}
		}
	}
	else if ( gubun == "TM" ) { 
		if ( obj.text.length == 0 ) return true;
		if ( obj.text.length != 6 ) { alert("[" + msg + "시간]을 [시,분,초]까지 정확히 입력하세요."); obj.focus(); return false; }		

		let tmp = obj.text ;
		if( eval(tmp.substring(0,2)) > 23 ) { alert("[" + msg + "시간중 시]를 정확히 입력하세요."); obj.focus(); return false; }	
		if( eval(tmp.substring(2,4)) > 59 ) { alert("[" + msg + "시간중 분]을 정확히 입력하세요."); obj.focus(); return false; }	
		if( eval(tmp.substring(4)) > 59 ) { alert("[" + msg + "시간중 초]를 정확히 입력하세요."); obj.focus(); return false; }	
	}
	else if ( gubun == "TM2" ) { 
		if ( obj.text.length == 0 ) return true;
		if ( obj.text.length != 4 ) { alert("[" + msg + "시간]을 [시,분]까지 정확히 입력하세요."); obj.focus(); return false; }		

		let tmp = obj.text ;
		if( eval(tmp.substring(0,2)) > 23 ) { alert("[" + msg + "시간중 시]를 정확히 입력하세요."); obj.focus(); return false; }	
		if( eval(tmp.substring(2,4)) > 59 ) { alert("[" + msg + "시간중 분]을 정확히 입력하세요."); obj.focus(); return false; }	

	}
	return true ;
}


