/*
 * 상장업무처리 메세지 처리
 */
scwin.LastJob = "";

/**
 * @method
 * @name fn_isProcess
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_isProcess = async function(gubun ) {
	if( gubun == 'I' ) LastJob = '저장' ;
	else if( gubun == 'U' ) LastJob = '수정' ;
	else if( gubun == 'D' ) LastJob = '삭제' ;
	else if( gubun == 'R' ) LastJob = '해제' ;
	else if( gubun == 'DSCL' ) LastJob = '안내문작성' ;

	if (! await $c.win.confirm($c.stf.getMessageParam("MSG-A006", LastJob)) )  return false ;

	return true ;
}

/*
 * 유가 매매거래 정지 메세지 처리
 */
/**
 * @method
 * @name fn_isTrdHaltProcess
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_isTrdHaltProcess = function(gubun ) {
	if( gubun == 'I' ) LastJob = '저장' ;

	if (! window.confirm($c.stf.getMessageParam("MSG-0026", LastJob)) )  return false ;

	return true ;
}

/*
 * 상장업무처리 메세지 처리
 */
/**
 * @method
 * @name fn_alertMsg
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_alertMsg = async function(gubun) {
	if( gubun == 'S' ) await $c.win.alert($c.stf.getMessageParam("MSG-A001", LastJob));
	else if( gubun == 'S1' ) await $c.win.alert($c.stf.getMessageParam("MSG-0001", LastJob));
	else if( gubun == 'F' ) await $c.win.alert($c.stf.getMessageParam("MSG-A002", LastJob));
}

/*
 * 상장업무처리 NoUpdate 메세지 처리
