 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_mst_check = function( param_Dts , gubun ) {
	let url = "/fiscalYearChange.do?method=searchFiscalYearChange" + 
				"&DIV_IDX="+scwin.glb.DIV_IDX_FSC_MST + "&TRS_IDX="+scwin.TRS_IDX_NEWSEL + "&ISUR_CD=" + Isur_cd + "&GUBUN_CD=" + gubun  ;
	param_Dts.DataID = encodeURI(url);
	param_Dts.reset();	

