/**
 * @method
 * @name fn_checkDoubleInput
 * @description desc 신규상장시 중복입력여부를 체크
 * @param
 * @returns
 * @hidden N
 * @exception 
 * @migrationStatus
 * @example
 */
scwin.fn_checkDoubleInput = async function(vIsurCd) {

    const param = { "isurCd" : vIsurCd}

    const sbmOptions = {
        id : "sbm_duplicate",
        action : "/api/listing/lstproc/stock/newlisting/select-check-duplicate",
        method : "get",
        isProcessMsg : false
    };

    const res =  await $c.sbm.executeDynamic(sbmOptions,param);
    if (res.responseJSON.body.dbinputYn == 'Y') {
        $c.win.alert("[해당종목은 이미 신규상장처리중이라 신규입력할 수 없습니다.]");
        return true;
    } else if (res.responseJSON.body.dbinputYn == 'N') {
        return false;
    }
}



/**
 * @method
 * @name fn_checkAcntclsMM
 * @description desc 결산월체크
 * @param
 * @returns
 * @hidden N
 * @exception 
 * @migrationStatus
 * @example
 */
 scwin.fn_checkAcntclsMM = function(obj) {
    if (obj.length == 1) {
        $c.win.alert("[결산월]을 올바르게 입력하세요. 1월 -> 01월");
        obj.focus();
        return false;
    } else if (obj.length == 2) {
        if (parseInt(obj.getValue(), 10) > 12 ) {
            $c.win.alert("[결산월]이 12월을 초과하였습니다. 다시입력하세요");
            obj.focus();
            return false;
        }
    } else if (obj.length == 4) {
        if (parseInt(obj.getValue().substring(0,2), 10) > 12 ) {
            $c.win.alert("[결산월]이 12월을 초과하였습니다. 다시입력하세요");
            obj.focus();
            return false; 
        }
    }

    return true;
}


scwin.fn_checkAcntclsMMDD = function(obj) {
    if (obj.getValue().length != 4) {
        alert("[결산월일]을 올바르게 입력하세요. 1월1일 -> 01월01일");obj.focus();return false;
    }

    if (parseInt(obj.getValue().substring(0, 2), 10) > 12 ) {
        alert("[입력월]이 12월을 초과하였습니다. 다시입력하세요");
        obj.focus();
        return false;
    }

    if (parseInt(obj.getValue().substring(2, 4), 10) > 31 ) {
        alert("[입력일]이 31일을 초과하였습니다. 다시입력하세요");obj.focus();return false;
    }
    return true;
}

scwin.fn_checkDistPay = function (dts_obj) {
    let isResult = false;
    for (i = 1;  i <= dts_obj.CountRow; i++) {
        let mmdd = dts_obj.NameString(i, "EARNG_DISTR_BAS_MM") + dts_obj.NameString(i, "EARNG_DISTR_BAS_DD");
        if( mmdd != ""  && mmdd.length != 4 ) {
            alert("입력한 분배기준일 항목중 [(월,일)]을 정확히 입력해주세요. \n\n예 : 5월1일 -> 0501 " );  return false;
            break;
        }
        isResult = true;
    }
    return isResult;
}


/**
