 */
 scwin.fn_read_sync_distr_pay = function(dtsObj, vBzProcsNo) {
    let url = "/Newlisting.do?method=selectManagement&inputMessageId=NEWLISTING_SEARCH_OUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_DIST_PAY;
    url += "&BZ_PROCS_NO=" + vBzProcsNo;
    dtsObj.DataID = encodeURI(url);
    dtsObj.Reset();
}

/**
 * 신규상장시 분배기준일정보를 입력하기 위해 데이타 셋을 갯수만큼 초기화함
 */
scwin.fn_initDistrPayGridData = function (dtsObj, initYn) {
    if (initYn == "N") {
        let vdtsDistrPayrowCnt = dtsObj.CountRow;
        for (i = vdtsDistrPayrowCnt; i <12; i++) {
            dtsObj.AddRow();
        }
    } else if (initYn == "Y") {
        for (j = 0; j <12; j++) {
            dtsObj.AddRow();
        }
    }
    dtsObj.RowPosition = 1;
}


