/**
* 변경전 주식수, 자본금 가져오기
*/
scwin.fn_bf_read_sync2 = async function (dtsObj, txb_ISU_CD, edt_BF_ACC_ISU_SHRS, edt_BF_ACC_ISU_CAP) {

    const param  = {
        isuCd : $c.stf.getObjectValue(txb_ISU_CD)
    } ;

    const sbmOptions = {
        id : "sbm_before-isu-detail",
        method: "get",
        action : "/api/listing/lstproc/stock/issuance-manage/before-isu-detail",
        isProcessMsg : false
    };

	const res = await $c.sbm.executeDynamic(sbmOptions,param);
    if (res.responseJSON.success) {
        if(res.responseJSON.body.bfAccIsuShrs !== null && res.responseJSON.body.bfAccIsuCap !== null ){
            $c.stf.setObjectValue(edt_BF_ACC_ISU_SHRS, res.responseJSON.body.bfAccIsuShrs);
            $c.stf.setObjectValue(edt_BF_ACC_ISU_CAP, res.responseJSON.body.bfAccIsuCap);
        }else{
            $c.stf.setObjectValue(edt_BF_ACC_ISU_SHRS, 0);
            $c.stf.setObjectValue(edt_BF_ACC_ISU_CAP, 0);
        }
    }
}

scwin.setButtonDepCd = async function(isurCd, userInfo, arrBtn) {

    if (userInfo.duty == 'Y'||  userInfo.dutyChrg == 'Y') { 
    } else {
        const param  = {
            isurCd : isurCd
        } ;

        const sbmOptions = {
            id : "sbm_select-corp-dep-cd",
            method: "get",
            action : "/api/listing/common/stock/select-corp-dep-cd",
            isProcessMsg : false
        };

        const res = await $c.sbm.executeDynamic(sbmOptions,param);

        if (res.responseJSON.success) {
            if (userInfo.depCd != res.responseJSON.body.depCd) {
                for(let i=0 ; i < arrBtn.length; i++){
                    arrBtn[i].setDisabled(true);
                }
            }
        }
    }
}
